/** Application review and referral eligibility state. */
export type AffiliateStatus = "pending" | "approved" | "suspended";
/** Percentage points or a fixed amount in currency minor units. */
export type CommissionType = "percent" | "flat";
/** Review and settlement state; payouts alone move commissions to paid. */
export type CommissionStatus = "pending" | "approved" | "paid" | "voided";
/** Manual payment outcome; failed batches release their reserved commissions. */
export type PayoutStatus = "pending" | "sent" | "failed";

/** Partner profile with ISO timestamp strings and optional administrative notes. */
export interface Affiliate {
	id: string;
	/** Authenticated account that exclusively owns this profile's portal. */
	userId: string;
	name: string;
	email: string;
	code: string;
	status: AffiliateStatus;
	/** Payment instructions stored as text, without processor-specific validation. */
	payoutDetails?: string | null;
	/** Administrative notes, omitted from portal responses. */
	notes?: string | null;
	commissionType?: CommissionType | null;
	commissionValue?: number | null;
	createdAt: string;
	updatedAt: string;
}
/** Recorded visit; its stored ISO timestamp determines cookie attribution eligibility. */
export interface ReferralClick {
	id: string;
	affiliateId: string;
	code: string;
	landingPath?: string | null;
	referrer?: string | null;
	/** Optional hash supplied by a trusted integration; HTTP tracking does not collect IPs. */
	ipHash?: string | null;
	userAgent?: string | null;
	createdAt: string;
}
/** Attributed order/event with a safe integer amount in currency minor units. */
export interface Conversion {
	id: string;
	affiliateId: string;
	clickId?: string | null;
	/** Stable order/event identifier used to deduplicate conversion retries. */
	externalRef?: string | null;
	amount: number;
	currency: string;
	status: "pending" | "approved" | "rejected";
	createdAt: string;
}
/** Earnings from one conversion, expressed in currency minor units with ISO timestamps. */
export interface Commission {
	id: string;
	affiliateId: string;
	conversionId: string;
	/** Pending or settled payout reservation; empty when available for a new batch. */
	payoutId?: string | null;
	amount: number;
	currency: string;
	status: CommissionStatus;
	createdAt: string;
	updatedAt: string;
}
/** One affiliate's manual payment batch in one currency; dates are ISO strings. */
export interface Payout {
	id: string;
	affiliateId: string;
	amount: number;
	currency: string;
	status: PayoutStatus;
	reference?: string | null;
	paidAt?: string | null;
	createdAt: string;
}
/** Offset pagination and filters for affiliate administration lists. */
export interface ListParams {
	limit?: number;
	offset?: number;
	affiliateId?: string;
	status?: string;
	currency?: string;
}
/** A page of records and the total count before pagination. */
export interface ListResult<T> {
	items: T[];
	total: number;
	limit: number;
	offset: number;
}
/** Referral counts and commission minor-unit totals, grouped separately per currency. */
export interface AffiliateStats {
	clicks: number;
	conversions: number;
	totals: {
		currency: string;
		pending: number;
		approved: number;
		paid: number;
		voided: number;
	}[];
}
/** HTTP(S) landing-page template and optional banner link shown to partners. */
export interface MarketingAsset {
	name: string;
	url: string;
	description?: string;
	bannerUrl?: string;
}
/** One account's profile, totals, recent financial history, and program marketing assets. */
export interface AffiliatePortal {
	affiliate: Affiliate | null;
	stats: AffiliateStats;
	commissions: Commission[];
	payouts: Payout[];
	assets: MarketingAsset[];
}
/** Pending-profile input; administrators supply ownership, applications use request identity. */
export interface CreateAffiliateInput {
	userId: string;
	name: string;
	email: string;
	code?: string;
	payoutDetails?: string;
}
/** Administrative profile edits; commission override type and value must be set or cleared together. */
export interface UpdateAffiliateInput {
	name?: string;
	email?: string;
	code?: string;
	status?: AffiliateStatus;
	payoutDetails?: string | null;
	notes?: string | null;
	commissionType?: CommissionType | null;
	commissionValue?: number | null;
}
/** A referral visit and optional metadata supplied by the tracking transport or trusted caller. */
export interface TrackClickInput {
	code: string;
	landingPath?: string;
	referrer?: string;
	ipHash?: string;
	userAgent?: string;
}
/** Verified order/event amount and attribution; omitted attribution returns null without a request fallback. */
export interface CreateConversionInput {
	externalRef?: string;
	amount: number;
	currency?: string;
	attribution?: { code?: string; clickId?: string };
}
/** Reserve selected or all available approved commissions for one affiliate and currency. */
export interface CreatePayoutInput {
	affiliateId: string;
	currency: string;
	commissionIds?: string[];
}
/** Attribution window, default commission rule, and optional partner marketing assets. */
export interface AffiliateOptions {
	/** Trusted HTTP(S) site origin for tracking redirects when the API uses a separate origin. */
	siteOrigin?: string;
	/** Number of days a stored referral click remains eligible. Defaults to 30. */
	attributionWindowDays?: number;
	/** Whether a new tracked referral replaces the existing cookie. Defaults to last_touch. */
	attributionMode?: "first_touch" | "last_touch";
	/** Default commission rule, unless the affiliate has an override. Defaults to percent. */
	defaultCommissionType?: CommissionType;
	/** Percentage (up to two decimals) or integer minor units for flat rules. Defaults to 20. */
	defaultCommissionValue?: number;
	/** Optional landing page templates and banner metadata displayed in the portal. */
	marketingAssets?: MarketingAsset[];
}

import { z } from "zod";

export const affiliateCodeSchema = z
	.string()
	.trim()
	.min(3)
	.max(64)
	.regex(/^[a-z0-9]+(?:-[a-z0-9]+)*$/);
export const moneySchema = z
	.number()
	.int()
	.nonnegative()
	.max(Number.MAX_SAFE_INTEGER);
export const currencySchema = z.string().regex(/^[A-Z]{3}$/);
export const affiliateStatusSchema = z.enum([
	"pending",
	"approved",
	"suspended",
]);
export const commissionTypeSchema = z.enum(["percent", "flat"]);
export const commissionStatusSchema = z.enum([
	"pending",
	"approved",
	"paid",
	"voided",
]);
export const payoutStatusSchema = z.enum(["pending", "sent", "failed"]);
export const idSchema = z.object({ id: z.string().min(1) });
export const listSchema = z.object({
	limit: z.coerce.number().int().min(1).max(100).optional(),
	offset: z.coerce.number().int().nonnegative().optional(),
	affiliateId: z.string().min(1).optional(),
	status: z.string().optional(),
	currency: currencySchema.optional(),
});
export const affiliateListSchema = listSchema
	.pick({ limit: true, offset: true, status: true })
	.extend({ status: affiliateStatusSchema.optional() });
export const applicationSchema = z.object({
	name: z.string().trim().min(1).max(200),
	email: z.email().max(320),
	code: affiliateCodeSchema.optional(),
	payoutDetails: z.string().max(10000).optional(),
});
export const createAffiliateSchema = applicationSchema.extend({
	userId: z.string().min(1),
});
export const updateAffiliateSchema = applicationSchema.partial().extend({
	payoutDetails: z.string().max(10000).nullable().optional(),
	status: affiliateStatusSchema.optional(),
	notes: z.string().max(10000).nullable().optional(),
	commissionType: commissionTypeSchema.nullable().optional(),
	commissionValue: z.number().finite().nonnegative().nullable().optional(),
});
export const updatePortalSchema = applicationSchema
	.partial()
	.extend({ payoutDetails: z.string().max(10000).nullable().optional() });
export const trackClickSchema = z.object({
	code: affiliateCodeSchema,
	landingPath: z.string().max(2048).optional(),
	referrer: z.string().max(2048).optional(),
	ipHash: z.string().max(256).optional(),
	userAgent: z.string().max(2048).optional(),
});
export const createConversionSchema = z.object({
	externalRef: z.string().min(1).max(255).optional(),
	amount: moneySchema,
	currency: currencySchema.default("USD"),
	attribution: z
		.object({
			code: affiliateCodeSchema.optional(),
			clickId: z.string().min(1).optional(),
		})
		.refine(
			(v) => v.code || v.clickId,
			"Attribution requires a code or click ID",
		)
		.optional(),
});
export const updateCommissionSchema = z.object({
	status: z.enum(["approved", "voided"]),
});
export const createPayoutSchema = z.object({
	affiliateId: z.string().min(1),
	currency: currencySchema,
	commissionIds: z.array(z.string().min(1)).min(1).max(1000).optional(),
});
export const updatePayoutSchema = z.object({
	status: z.enum(["sent", "failed"]),
	reference: z.string().max(1000).optional(),
});

import { definePermissions, permission } from "@btst/stack/authorization";
import { z } from "zod";

const affiliateFacts = z.object({
	affiliateId: z.string(),
	userId: z.string(),
	status: z.enum(["pending", "approved", "suspended"]),
});

/** Administrative permissions are separate from identity-scoped portal access. */
export const affiliatePermissions = definePermissions("affiliate", {
	affiliate: {
		read: permission(
			z.discriminatedUnion("scope", [
				z.object({ scope: z.literal("collection") }),
				z.object({ scope: z.literal("record"), affiliateId: z.string() }),
			]),
		),
		create: permission(),
		update: permission(affiliateFacts),
		delete: permission(affiliateFacts),
	},
	application: { create: permission() },
	portal: { read: permission(), update: permission() },
	tracking: { track: permission() },
	conversion: { create: permission() },
	commission: {
		read: permission(),
		update: permission(
			z.object({
				commissionId: z.string(),
				affiliateId: z.string(),
				status: z.enum(["pending", "approved", "paid", "voided"]),
			}),
		),
	},
	payout: {
		read: permission(),
		create: permission(
			z.object({ affiliateId: z.string(), currency: z.string() }),
		),
		update: permission(
			z.object({
				payoutId: z.string(),
				affiliateId: z.string(),
				status: z.enum(["pending", "sent", "failed"]),
			}),
		),
		export: permission(),
	},
});

"use client";

import { lazy, useEffect, useState, type ReactNode } from "react";
import { ComposedRoute } from "@btst/stack/client/components";
import { affiliatePermissions } from "../../permissions";
import { AffiliateError, AffiliateLoading, AffiliateNotFound } from "./shared";

const Affiliates = lazy(() =>
	import("./pages/affiliates-page.internal").then((m) => ({
		default: m.AffiliatesPage,
	})),
);
const Detail = lazy(() =>
	import("./pages/affiliate-detail-page.internal").then((m) => ({
		default: m.AffiliateDetailPage,
	})),
);
const Commissions = lazy(() =>
	import("./pages/commissions-page.internal").then((m) => ({
		default: m.CommissionsPage,
	})),
);
const Payouts = lazy(() =>
	import("./pages/payouts-page.internal").then((m) => ({
		default: m.PayoutsPage,
	})),
);
const Apply = lazy(() =>
	import("./pages/affiliate-apply-page.internal").then((m) => ({
		default: m.AffiliateApplyPage,
	})),
);
const Portal = lazy(() =>
	import("./pages/affiliate-portal-page.internal").then((m) => ({
		default: m.AffiliatePortalPage,
	})),
);

function BrowserPage({ children }: { children: ReactNode }) {
	const [mounted, setMounted] = useState(false);
	useEffect(() => setMounted(true), []);
	return mounted ? children : <AffiliateLoading />;
}

const boundary = {
	ErrorComponent: AffiliateError,
	LoadingComponent: AffiliateLoading,
	NotFoundComponent: AffiliateNotFound,
	onError: (error: Error) => console.error("[btst/affiliate]", error),
};

function AffiliateList() {
	return (
		<BrowserPage>
			<Affiliates />
		</BrowserPage>
	);
}
function AffiliateDetail(props: { id: string }) {
	return (
		<BrowserPage>
			<Detail {...props} />
		</BrowserPage>
	);
}
function CommissionList() {
	return (
		<BrowserPage>
			<Commissions />
		</BrowserPage>
	);
}
function PayoutList() {
	return (
		<BrowserPage>
			<Payouts />
		</BrowserPage>
	);
}
function Application() {
	return (
		<BrowserPage>
			<Apply />
		</BrowserPage>
	);
}
function PortalDashboard() {
	return (
		<BrowserPage>
			<Portal />
		</BrowserPage>
	);
}

export function AffiliatesPageComponent() {
	return (
		<ComposedRoute
			{...boundary}
			path="/affiliate/admin/affiliates"
			permission={affiliatePermissions.affiliate.read({ scope: "collection" })}
			PageComponent={AffiliateList}
		/>
	);
}
export function AffiliateDetailPageComponent({ id }: { id: string }) {
	return (
		<ComposedRoute
			{...boundary}
			path={`/affiliate/admin/affiliates/${id}`}
			permission={affiliatePermissions.affiliate.read({
				scope: "record",
				affiliateId: id,
			})}
			PageComponent={AffiliateDetail}
			props={{ id }}
		/>
	);
}
export function CommissionsPageComponent() {
	return (
		<ComposedRoute
			{...boundary}
			path="/affiliate/admin/commissions"
			permission={affiliatePermissions.commission.read()}
			PageComponent={CommissionList}
		/>
	);
}
export function PayoutsPageComponent() {
	return (
		<ComposedRoute
			{...boundary}
			path="/affiliate/admin/payouts"
			permission={affiliatePermissions.payout.read()}
			PageComponent={PayoutList}
		/>
	);
}
export function AffiliateApplyPageComponent() {
	return (
		<ComposedRoute
			{...boundary}
			path="/affiliate/apply"
			permission={affiliatePermissions.application.create()}
			PageComponent={Application}
		/>
	);
}
export function AffiliatePortalPageComponent() {
	return (
		<ComposedRoute
			{...boundary}
			path="/affiliate/portal"
			permission={affiliatePermissions.portal.read()}
			PageComponent={PortalDashboard}
		/>
	);
}

"use client";

import { useState, type FormEvent } from "react";
import {
	useIdentity,
	usePluginOverrides,
	usePluginSiteNavigation,
} from "@btst/stack/context";
import { useApplyAffiliate } from "@btst/plugin-affiliate/client/hooks";
import { AFFILIATE_PLUGIN_ID } from "../../constants";
import type { AffiliatePluginOverrides } from "../../overrides";
import {
	ActionNotice,
	AffiliatePage,
	ProfileFields,
	readProfile,
	useAffiliateAction,
} from "../shared";

export function AffiliateApplyPage() {
	const { identity } = useIdentity();
	const [applied, setApplied] = useState(false);
	const apply = useApplyAffiliate();
	const action = useAffiliateAction();
	const { Link, resolve } = usePluginSiteNavigation(AFFILIATE_PLUGIN_ID);
	const { localization } =
		usePluginOverrides<AffiliatePluginOverrides>(AFFILIATE_PLUGIN_ID);
	const save = (event: FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		const fields = new FormData(event.currentTarget);
		void action.run(async () => {
			await apply.mutateAsync(readProfile(fields));
			setApplied(true);
		}, "Application submitted");
	};
	return (
		<AffiliatePage
			title={localization?.apply ?? "Become an affiliate"}
			description="Apply for a referral code and earn commissions on attributed conversions after approval."
			admin={false}
		>
			<div className="affiliate-application">
				<ActionNotice {...action} />
				{applied ? (
					<section className="affiliate-stack">
						<h2>Your application is pending review</h2>
						<p>
							You can view your status and update your payout details in the
							affiliate portal.
						</p>
						<Link
							className="affiliate-primary"
							href={resolve("affiliate/portal").href}
						>
							Open affiliate portal
						</Link>
					</section>
				) : (
					<form className="affiliate-stack" onSubmit={save}>
						<fieldset disabled={action.pending}>
							<ProfileFields
								defaults={{ name: identity?.name, email: identity?.email }}
							/>
							<button className="affiliate-primary" type="submit">
								{action.pending ? "Submitting…" : "Submit application"}
							</button>
						</fieldset>
					</form>
				)}
			</div>
		</AffiliatePage>
	);
}

"use client";

import type { FormEvent } from "react";
import { PermissionAccess, usePluginSiteNavigation } from "@btst/stack/context";
import { affiliatePermissions } from "../../../permissions";
import type { AffiliateStatus, CommissionType } from "../../../types";
import {
	useAffiliate,
	useDeleteAffiliate,
	useUpdateAffiliate,
} from "@btst/plugin-affiliate/client/hooks";
import { AFFILIATE_PLUGIN_ID } from "../../constants";
import {
	ActionNotice,
	AffiliatePage,
	ProfileFields,
	readProfile,
	Stats,
	Status,
	useAffiliateAction,
} from "../shared";

export function AffiliateDetailPage({ id }: { id: string }) {
	const { data } = useAffiliate(id);
	const { affiliate, stats } = data;
	const update = useUpdateAffiliate();
	const remove = useDeleteAffiliate();
	const action = useAffiliateAction();
	const { Link, resolve, navigate } =
		usePluginSiteNavigation(AFFILIATE_PLUGIN_ID);
	const facts = {
		affiliateId: affiliate.id,
		userId: affiliate.userId,
		status: affiliate.status,
	};
	const save = (event: FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		const fields = new FormData(event.currentTarget);
		const commissionType = String(fields.get("commissionType") ?? "");
		const commissionValue = String(fields.get("commissionValue") ?? "");
		void action.run(async () => {
			if (commissionType && !commissionValue.trim())
				throw new Error(
					"Enter a commission value or select the program default.",
				);
			await update.mutateAsync({
				id,
				data: {
					...readProfile(fields),
					status: String(fields.get("status")) as AffiliateStatus,
					notes: String(fields.get("notes") ?? ""),
					commissionType: commissionType
						? (commissionType as CommissionType)
						: null,
					commissionValue: commissionType ? Number(commissionValue) : null,
				},
			});
		}, "Affiliate profile saved");
	};
	return (
		<AffiliatePage
			title={affiliate.name}
			description={affiliate.email}
			action={<Status value={affiliate.status} />}
		>
			<Link href={resolve("affiliate/admin/affiliates").href}>
				Back to affiliates
			</Link>
			<Stats stats={stats} />
			<ActionNotice {...action} />
			<PermissionAccess
				permission={affiliatePermissions.affiliate.update(facts)}
			>
				<form
					className="affiliate-stack"
					key={affiliate.updatedAt}
					onSubmit={save}
				>
					<h2>Profile and commission rule</h2>
					<p className="affiliate-small affiliate-muted">
						Account: {affiliate.userId}
					</p>
					<fieldset disabled={action.pending}>
						<ProfileFields affiliate={affiliate} admin />
						<div className="affiliate-actions">
							<button className="affiliate-primary" type="submit">
								{action.pending ? "Saving…" : "Save profile"}
							</button>
						</div>
					</fieldset>
				</form>
			</PermissionAccess>
			<PermissionAccess
				permission={affiliatePermissions.affiliate.delete(facts)}
			>
				<section className="affiliate-section affiliate-stack">
					<h2>Remove affiliate</h2>
					<p className="affiliate-muted">
						Only affiliates without conversions, commissions, or payouts can be
						deleted. Suspend a partner to stop new referrals and preserve their
						history.
					</p>
					<div>
						<button
							type="button"
							disabled={action.pending}
							onClick={() => {
								if (
									window.confirm(
										`Delete ${affiliate.name}? This removes their affiliate profile.`,
									)
								)
									void action.run(async () => {
										await remove.mutateAsync(id);
										await navigate("affiliate/admin/affiliates");
									});
							}}
						>
							Delete affiliate
						</button>
					</div>
				</section>
			</PermissionAccess>
		</AffiliatePage>
	);
}

"use client";

import { useState, type FormEvent } from "react";
import {
	PermissionAccess,
	usePluginOverrides,
	usePluginSiteNavigation,
} from "@btst/stack/context";
import { affiliatePermissions } from "../../../permissions";
import {
	useAffiliateDashboard,
	useReferralLink,
	useUpdateAffiliateProfile,
} from "@btst/plugin-affiliate/client/hooks";
import { AFFILIATE_PLUGIN_ID } from "../../constants";
import type { AffiliatePluginOverrides } from "../../overrides";
import {
	ActionNotice,
	AffiliatePage,
	Field,
	ProfileFields,
	readProfile,
	Stats,
	Status,
	date,
	money,
	useAffiliateAction,
} from "../shared";

function assetHref(value: string) {
	try {
		const url = new URL(value, window.location.origin);
		return ["https:", "http:"].includes(url.protocol) ? url.href : undefined;
	} catch {
		return undefined;
	}
}

export function AffiliatePortalPage() {
	const { data } = useAffiliateDashboard();
	const [landingPath, setLandingPath] = useState("/");
	const [link, setLink] = useState("");
	const [editing, setEditing] = useState(false);
	const createLink = useReferralLink();
	const update = useUpdateAffiliateProfile();
	const action = useAffiliateAction();
	const { Link, resolve } = usePluginSiteNavigation(AFFILIATE_PLUGIN_ID);
	const { localization } =
		usePluginOverrides<AffiliatePluginOverrides>(AFFILIATE_PLUGIN_ID);
	const { affiliate, stats, commissions, payouts, assets } = data;
	const save = (event: FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		const fields = new FormData(event.currentTarget);
		void action.run(async () => {
			await update.mutateAsync(readProfile(fields));
			setEditing(false);
			setLink("");
		}, "Profile saved");
	};
	if (!affiliate)
		return (
			<AffiliatePage
				title={localization?.portal ?? "Affiliate portal"}
				admin={false}
			>
				<section className="affiliate-stack">
					<h2>Start with an affiliate application</h2>
					<p>
						Apply to receive a referral code and track your commissions here.
					</p>
					<div>
						<Link
							className="affiliate-primary"
							href={resolve("affiliate/apply").href}
						>
							Apply to become an affiliate
						</Link>
					</div>
				</section>
			</AffiliatePage>
		);
	return (
		<AffiliatePage
			title={localization?.portal ?? "Affiliate portal"}
			description={`Referral activity and earnings for ${affiliate.name}.`}
			admin={false}
			action={<Status value={affiliate.status} />}
		>
			<ActionNotice {...action} />
			{affiliate.status !== "approved" && (
				<p className="affiliate-notice">
					{affiliate.status === "pending"
						? "Your application is pending review. Referral tracking starts after approval."
						: "Your affiliate account is suspended. New referrals are not attributed. Contact the program administrator for help."}
				</p>
			)}
			<Stats stats={stats} />
			<section className="affiliate-section affiliate-stack">
				<h2>Your referral link</h2>
				<p className="affiliate-muted">
					Code: <strong>{affiliate.code}</strong>. Choose a landing page on this
					site. Visits through your link are recorded before the visitor reaches
					that page.
				</p>
				<form
					className="affiliate-toolbar"
					onSubmit={(event) => {
						event.preventDefault();
						void action.run(async () => {
							const next = createLink(affiliate.code, landingPath);
							setLink(next);
						}, "Referral link generated");
					}}
				>
					<Field
						label="Landing page path"
						hint="For example, /pricing or /products?category=books."
					>
						<input
							value={landingPath}
