"use client";

import { useState, type FormEvent } from "react";
import {
	PermissionAccess,
	usePluginOverrides,
	usePluginSiteNavigation,
} from "@btst/stack/context";
import { affiliatePermissions } from "../../../permissions";
import {
	useCreatePayout,
	usePayoutExport,
	usePayouts,
	useUpdatePayout,
} from "@btst/plugin-affiliate/client/hooks";
import { AFFILIATE_PLUGIN_ID } from "../../constants";
import type { AffiliatePluginOverrides } from "../../overrides";
import type { Payout } from "../../../types";
import {
	ActionNotice,
	AffiliatePage,
	Field,
	Pagination,
	Status,
	money,
	date,
	useAffiliateAction,
} from "../shared";

export function PayoutsPage() {
	const [status, setStatus] = useState("");
	const [offset, setOffset] = useState(0);
	const [affiliateId, setAffiliateId] = useState("");
	const [currency, setCurrency] = useState("USD");
	const [recording, setRecording] = useState<Payout | null>(null);
	const { data } = usePayouts({
		status: status || undefined,
		offset,
		limit: 25,
	});
	const exportCSV = usePayoutExport({ status: status || undefined });
	const create = useCreatePayout();
	const update = useUpdatePayout();
	const action = useAffiliateAction();
	const { Link, resolve } = usePluginSiteNavigation(AFFILIATE_PLUGIN_ID);
	const { localization } =
		usePluginOverrides<AffiliatePluginOverrides>(AFFILIATE_PLUGIN_ID);
	const save = (event: FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		void action.run(async () => {
			await create.mutateAsync({ affiliateId, currency });
		}, "Payout batch created. Arrange the payment, then record its result below.");
	};
	const record = (event: FormEvent<HTMLFormElement>) => {
		event.preventDefault();
		if (!recording) return;
		const fields = new FormData(event.currentTarget);
		const payout = recording;
		void action.run(async () => {
			await update.mutateAsync({
				id: payout.id,
				status: String(fields.get("status")) as "sent" | "failed",
				reference: String(fields.get("reference") ?? ""),
			});
			setRecording(null);
		}, "Payout result recorded");
	};
	return (
		<AffiliatePage
			title={localization?.payouts ?? "Payouts"}
			description="Group approved commissions, arrange payment, and record the result."
			action={
				<PermissionAccess permission={affiliatePermissions.payout.export()}>
					<button
						type="button"
						disabled={action.pending || exportCSV.isFetching}
						onClick={() =>
							void action.run(async () => {
								const result = await exportCSV.refetch();
								if (result.error) throw result.error;
								if (!result.data)
									throw new Error(
										"The payout CSV could not be exported. Try again.",
									);
								const url = URL.createObjectURL(
									new Blob([result.data.csv], {
										type: "text/csv;charset=utf-8",
									}),
								);
								const anchor = document.createElement("a");
								anchor.href = url;
								anchor.download = "affiliate-payouts.csv";
								anchor.click();
								URL.revokeObjectURL(url);
							}, "Payouts exported")
						}
					>
						Export CSV
					</button>
				</PermissionAccess>
			}
		>
			<ActionNotice {...action} />
			<form className="affiliate-panel affiliate-stack" onSubmit={save}>
				<h2>Create payout batch</h2>
				<p className="affiliate-muted">
					Includes all approved, unpaid commissions for one affiliate and
					currency. Payment is arranged manually.
				</p>
				<fieldset disabled={action.pending}>
					<div className="affiliate-form-grid">
						<Field label="Affiliate ID">
							<input
								value={affiliateId}
								onChange={(event) => setAffiliateId(event.target.value)}
								required
							/>
						</Field>
						<Field label="Currency">
							<input
								value={currency}
								onChange={(event) =>
									setCurrency(event.target.value.toUpperCase())
								}
								pattern="[A-Z]{3}"
								maxLength={3}
								minLength={3}
								required
							/>
						</Field>
					</div>
					<PermissionAccess
						permission={affiliatePermissions.payout.create({
							affiliateId,
							currency,
						})}
					>
						<button className="affiliate-primary" type="submit">
							{create.isPending ? "Creating…" : "Create payout batch"}
						</button>
					</PermissionAccess>
				</fieldset>
			</form>
			{recording && (
				<form className="affiliate-panel affiliate-stack" onSubmit={record}>
					<h2>Record payout result</h2>
					<p>
						{money(recording.amount, recording.currency)} for affiliate{" "}
						{recording.affiliateId}
					</p>
					<fieldset disabled={action.pending}>
						<div className="affiliate-form-grid">
							<Field label="Payment result">
								<select name="status" defaultValue="sent">
									<option value="sent">Sent</option>
									<option value="failed">Failed</option>
								</select>
							</Field>
							<Field label="Payment reference">
								<input
									name="reference"
									maxLength={1000}
									placeholder="Bank transfer or accounting reference"
								/>
							</Field>
						</div>
						<div className="affiliate-actions">
							<button className="affiliate-primary" type="submit">
								Save payout result
							</button>
							<button type="button" onClick={() => setRecording(null)}>
								Cancel
							</button>
						</div>
					</fieldset>
				</form>
			)}
			<div className="affiliate-toolbar">
				<Field label="Filter by status">
					<select
						value={status}
						onChange={(event) => {
							setStatus(event.target.value);
							setOffset(0);
						}}
					>
						<option value="">All statuses</option>
						<option value="pending">Pending</option>
						<option value="sent">Sent</option>
						<option value="failed">Failed</option>
					</select>
				</Field>
			</div>
			{data.items.length === 0 ? (
				<p className="affiliate-empty">
					No payouts match. Create a batch when an affiliate has approved
					commissions.
				</p>
			) : (
				<div
					className="affiliate-table-scroll"
					role="region"
					aria-label="Payout history"
					tabIndex={0}
				>
					<table>
						<caption className="affiliate-sr-only">
							Manual affiliate payouts
						</caption>
						<thead>
							<tr>
								<th>Affiliate</th>
								<th className="affiliate-number">Amount</th>
								<th>Status</th>
								<th>Reference / date</th>
								<th>Actions</th>
							</tr>
						</thead>
						<tbody>
							{data.items.map((payout) => (
								<tr key={payout.id}>
									<td>
										<Link
											href={
												resolve(
													"affiliate/admin/affiliates",
													encodeURIComponent(payout.affiliateId),
												).href
											}
										>
											{payout.affiliateId}
										</Link>
										<p className="affiliate-small affiliate-muted">
											{payout.id}
										</p>
									</td>
									<td className="affiliate-number">
										{money(payout.amount, payout.currency)}
									</td>
									<td>
										<Status value={payout.status} />
									</td>
									<td>
										{payout.reference || "No reference"}
										<p className="affiliate-small affiliate-muted">
											{date(payout.paidAt ?? payout.createdAt)}
										</p>
									</td>
									<td>
										{payout.status === "pending" && (
											<PermissionAccess
												permission={affiliatePermissions.payout.update({
													payoutId: payout.id,
													affiliateId: payout.affiliateId,
													status: payout.status,
												})}
											>
												<button
													type="button"
													disabled={action.pending}
													aria-label={`Record payout result ${payout.id}`}
													onClick={() => setRecording(payout)}
												>
													Record result
												</button>
											</PermissionAccess>
										)}
									</td>
								</tr>
							))}
						</tbody>
					</table>
				</div>
			)}
			<Pagination offset={offset} total={data.total} onChange={setOffset} />
		</AffiliatePage>
	);
}

"use client";

import { useState, type ReactNode } from "react";
import {
	PermissionAccess,
	usePluginOverrides,
	usePluginSiteNavigation,
} from "@btst/stack/context";
import type { FallbackProps } from "@btst/stack/client/components";
import { affiliatePermissions } from "../../permissions";
import type {
	Affiliate,
	AffiliateStats,
	CreateAffiliateInput,
} from "../../types";
import { AFFILIATE_PLUGIN_ID } from "../constants";
import type { AffiliatePluginOverrides } from "../overrides";

export function AffiliatePage({
	title,
	description,
	action,
	admin = true,
	children,
}: {
	title: string;
	description?: string;
	action?: ReactNode;
	admin?: boolean;
	children: ReactNode;
}) {
	const { Link, resolve } = usePluginSiteNavigation(AFFILIATE_PLUGIN_ID);
	const { localization } =
		usePluginOverrides<AffiliatePluginOverrides>(AFFILIATE_PLUGIN_ID);
	return (
		<div className="affiliate-page" data-testid="affiliate-page">
			<header className="affiliate-heading">
				<div>
					<h1>{title}</h1>
					{description && <p className="affiliate-muted">{description}</p>}
				</div>
				{action}
			</header>
			{admin && (
				<nav className="affiliate-nav" aria-label="Affiliate administration">
					<PermissionAccess
						permission={affiliatePermissions.affiliate.read({
							scope: "collection",
						})}
					>
						<Link href={resolve("affiliate/admin/affiliates").href}>
							{localization?.affiliates ?? "Affiliates"}
						</Link>
					</PermissionAccess>
					<PermissionAccess permission={affiliatePermissions.commission.read()}>
						<Link href={resolve("affiliate/admin/commissions").href}>
							{localization?.commissions ?? "Commissions"}
						</Link>
					</PermissionAccess>
					<PermissionAccess permission={affiliatePermissions.payout.read()}>
						<Link href={resolve("affiliate/admin/payouts").href}>
							{localization?.payouts ?? "Payouts"}
						</Link>
					</PermissionAccess>
				</nav>
			)}
			{children}
		</div>
	);
}

export function Field({
	label,
	hint,
	children,
}: {
	label: string;
	hint?: string;
	children: ReactNode;
}) {
	return (
		<label className="affiliate-field">
			<span>{label}</span>
			{children}
			{hint && <span className="affiliate-muted affiliate-small">{hint}</span>}
		</label>
	);
}

export function ProfileFields({
	affiliate,
	defaults,
	userId = false,
	admin = false,
}: {
	affiliate?: Affiliate;
	defaults?: { name?: string; email?: string };
	userId?: boolean;
	admin?: boolean;
}) {
	return (
		<div className="affiliate-form-grid">
			{userId && (
				<Field
					label="User ID"
					hint="The account that will own this affiliate portal."
				>
					<input name="userId" required maxLength={255} />
				</Field>
			)}
			<Field label="Name">
				<input
					name="name"
					required
					maxLength={200}
					autoComplete="name"
					defaultValue={affiliate?.name ?? defaults?.name ?? ""}
				/>
			</Field>
			<Field label="Email">
				<input
					name="email"
					type="email"
					required
					maxLength={320}
					autoComplete="email"
					defaultValue={affiliate?.email ?? defaults?.email ?? ""}
				/>
			</Field>
			<Field
				label="Referral code"
				hint="3–64 lowercase letters, numbers, or single hyphens. Leave blank to generate a code."
			>
				<input
					name="code"
					minLength={3}
					maxLength={64}
					pattern="[a-z0-9]+(-[a-z0-9]+)*"
					defaultValue={affiliate?.code ?? ""}
				/>
			</Field>
			<Field
				label="Payout details"
				hint="Payment instructions for the person arranging your payouts."
			>
				<textarea
					name="payoutDetails"
					rows={3}
					maxLength={10000}
					defaultValue={affiliate?.payoutDetails ?? ""}
				/>
			</Field>
			{admin && (
				<>
					<Field label="Status">
						<select name="status" defaultValue={affiliate?.status ?? "pending"}>
							{(!affiliate || affiliate.status === "pending") && (
								<option value="pending">Pending</option>
							)}
							<option value="approved">Approved</option>
							<option value="suspended">Suspended</option>
						</select>
					</Field>
					<Field label="Commission rule">
						<select
							name="commissionType"
							defaultValue={affiliate?.commissionType ?? ""}
						>
							<option value="">Program default</option>
							<option value="percent">Percentage</option>
							<option value="flat">Flat amount</option>
						</select>
					</Field>
					<Field
						label="Commission value"
						hint="Percentage points, or a flat amount in minor units (100 = USD 1.00)."
					>
						<input
							name="commissionValue"
							type="number"
							min="0"
							step="any"
							defaultValue={affiliate?.commissionValue ?? ""}
						/>
					</Field>
					<Field label="Internal notes">
						<textarea
							name="notes"
							maxLength={10000}
							rows={3}
							defaultValue={affiliate?.notes ?? ""}
						/>
					</Field>
				</>
			)}
		</div>
	);
}

export function readProfile(
	fields: FormData,
): Omit<CreateAffiliateInput, "userId"> {
	const code = String(fields.get("code") ?? "").trim();
	return {
		name: String(fields.get("name") ?? ""),
		email: String(fields.get("email") ?? ""),
		...(code ? { code } : {}),
		payoutDetails: String(fields.get("payoutDetails") ?? ""),
	};
}

export function useAffiliateAction() {
	const [error, setError] = useState("");
	const [message, setMessage] = useState("");
	const [pending, setPending] = useState(false);
	const run = async (action: () => Promise<void>, success = "") => {
		setError("");
		setMessage("");
		setPending(true);
		try {
			await action();
			setMessage(success);
		} catch (caught) {
			setError(
				caught instanceof Error
					? caught.message
					: "The change could not be saved. Try again.",
			);
		} finally {
			setPending(false);
		}
	};
	return { error, message, pending, run };
}

export function ActionNotice({
	error,
	message,
}: {
	error: string;
	message: string;
}) {
	return (
		<>
			{error && (
				<p role="alert" className="affiliate-error">
					{error}
				</p>
			)}
			{message && <p role="status">{message}</p>}
		</>
	);
}

export function Status({ value }: { value: string }) {
	return (
		<span className="affiliate-status" data-status={value}>
			{value.charAt(0).toUpperCase() + value.slice(1)}
		</span>
	);
}

export function money(amount: number, currency: string) {
	const formatter = new Intl.NumberFormat(undefined, {
		style: "currency",
		currency,
	});
	const digits = formatter.resolvedOptions().maximumFractionDigits ?? 2;
	return formatter.format(amount / 10 ** digits);
}

export function date(value: string) {
	return new Date(value).toLocaleDateString(undefined, {
		year: "numeric",
		month: "short",
		day: "numeric",
	});
}

export function Stats({ stats }: { stats: AffiliateStats }) {
	return (
		<section
			aria-label="Affiliate performance"
			className="affiliate-performance"
		>
			<dl className="affiliate-metrics">
				<div>
					<dt>Referral clicks</dt>
					<dd>{stats.clicks.toLocaleString()}</dd>
				</div>
				<div>
					<dt>Conversions</dt>
					<dd>{stats.conversions.toLocaleString()}</dd>
				</div>
			</dl>
			{stats.totals.length > 0 && (
				<div
					className="affiliate-table-scroll"
					role="region"
					aria-label="Commission totals"
					tabIndex={0}
				>
					<table>
						<caption className="affiliate-sr-only">
							Commission totals by currency
						</caption>
						<thead>
							<tr>
								<th>Currency</th>
								<th className="affiliate-number">Pending</th>
								<th className="affiliate-number">Approved</th>
								<th className="affiliate-number">Paid</th>
							</tr>
						</thead>
						<tbody>
							{stats.totals.map((total) => (
								<tr key={total.currency}>
									<th scope="row">{total.currency}</th>
									<td className="affiliate-number">
										{money(total.pending, total.currency)}
									</td>
									<td className="affiliate-number">
										{money(total.approved, total.currency)}
									</td>
									<td className="affiliate-number">
										{money(total.paid, total.currency)}
									</td>
								</tr>
							))}
						</tbody>
					</table>
				</div>
			)}
		</section>
	);
}

export function Pagination({
	offset,
	total,
	onChange,
}: {
	offset: number;
	total: number;
	onChange: (offset: number) => void;
}) {
	return (
		<div className="affiliate-pagination">
			<p className="affiliate-muted">
				{total === 0
					? "No results"
					: `${offset + 1}–${Math.min(offset + 25, total)} of ${total}`}
			</p>
			<div className="affiliate-actions">
				<button
					type="button"
					disabled={offset === 0}
					onClick={() => onChange(Math.max(0, offset - 25))}
				>
					Previous page
				</button>
				<button
					type="button"
					disabled={offset + 25 >= total}
					onClick={() => onChange(offset + 25)}
				>
					Next page
				</button>
			</div>
		</div>
	);
}

export function AffiliateLoading() {
	return (
		<div className="affiliate-page" role="status">
			Loading affiliate information…
		</div>
	);
}

export function AffiliateError({ error, resetErrorBoundary }: FallbackProps) {
	return (
		<div className="affiliate-page affiliate-stack" role="alert">
			<h1>Affiliate information unavailable</h1>
			<p>
				{error instanceof Error && error.message
					? error.message
					: "Check your access and try again."}
			</p>
			<button type="button" onClick={resetErrorBoundary}>
				Retry loading
			</button>
		</div>
	);
}

export function AffiliateNotFound({ message }: { message: string }) {
	return (
		<div className="affiliate-page">
			<h1>Affiliate not found</h1>
			<p>{message}</p>
		</div>
	);
}

